(()=>{'use strict';class Effects{constructor(){this.particles=[];this.floaters=[];this.trails=[];this.shake=0;this.flash=0}reset(){this.particles=[];this.floaters=[];this.trails=[];this.shake=0;this.flash=0}burst(x,y,power=1,type='hit'){const count=Math.min(32,Math.round(7+power*3));for(let i=0;i<count;i++){let a=i*Math.PI*2/count+(Math.random()-.5)*.5,v=.7+Math.random()*2.7;this.particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:.26+Math.random()*.38,max:.65,size:.025+Math.random()*.05,color:type==='catch'?(i%2?'#fff2a5':'#7fe5c1'):(i%2?'#ffc678':'#f27b50')})}this.shake=Math.max(this.shake,Math.min(1,power*.23));this.particles=this.particles.slice(-160)}trail(x,y){this.trails.push({x,y,life:.15,max:.15});if(this.trails.length>20)this.trails.shift()}label(x,y,text){this.floaters.push({x,y,text,life:.75,max:.75})}update(dt){for(const t of this.trails)t.life-=dt;this.trails=this.trails.filter(t=>t.life>0);for(const p of this.particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=3*dt;p.life-=dt}this.particles=this.particles.filter(p=>p.life>0);for(const t of this.floaters){t.y-=dt*.75;t.life-=dt}this.floaters=this.floaters.filter(t=>t.life>0);this.shake=Math.max(0,this.shake-dt*3);this.flash=Math.max(0,this.flash-dt*4)}draw(ctx,cam){ctx.save();for(const t of this.trails){const pos=cam.toScreen(t.x,t.y-1.0);ctx.globalAlpha=.2*(t.life/t.max);ctx.fillStyle="#74e3d1";ctx.beginPath();ctx.ellipse(pos.x,pos.y,Math.max(4,cam.scale*.22),Math.max(7,cam.scale*.42),0,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;for(const p of this.particles){const pos=cam.toScreen(p.x,p.y);ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(pos.x,pos.y,Math.max(1,p.size*cam.scale),0,2*Math.PI);ctx.fill()}ctx.globalAlpha=1;for(const t of this.floaters){const pos=cam.toScreen(t.x,t.y);ctx.globalAlpha=Math.min(1,t.life/.22);ctx.font=`1000 ${Math.max(19,cam.scale*.23)}px system-ui`;ctx.textAlign='center';ctx.lineWidth=5;ctx.strokeStyle='#173e42';ctx.strokeText(t.text,pos.x,pos.y);ctx.fillStyle='#fff0a8';ctx.fillText(t.text,pos.x,pos.y)}ctx.restore()}}window.BagEffects=Effects})();
